-- 네 낱말을 다 써 본다

@Test
void 네_낱말() {
    for (String kind : List.of("join", "innerJoin", "leftJoin", "rightJoin")) {
        em.clear();
        System.out.println("--- " + kind + " ---");
        JPAQuery<Member> q = queryFactory.selectFrom(member);
        switch (kind) {
            case "join"      -> q.join(member.team, team);
            case "innerJoin" -> q.innerJoin(member.team, team);
            case "leftJoin"  -> q.leftJoin(member.team, team);
            default          -> q.rightJoin(member.team, team);
        }
        System.out.println("건수: " + q.fetch().size());
    }
}

