@Test
void 두_번_조인() {
    QTeam t2 = new QTeam("t2");
    em.clear();
    queryFactory.selectFrom(member)
            .join(member.team, team)
            .join(member.team, t2)
            .where(team.name.eq("teamA"), t2.name.startsWith("team"))
            .fetch();
}

